def find_longest_increasing_sequence(n, a):
    from collections import deque

    a = deque(a)  # Use deque for efficient pop from both ends
    moves = []

    # Attempt to build a strictly increasing sequence
    for _ in range(n):
        if not a:
            break
        # Check if the leftmost or rightmost element can be added to the sequence
        if (not moves or (moves[-1] == 'R' and a[0] > a[-1]) or (moves[-1] == 'L' and a[0] > a[0])):
            moves.append('L')
            a.popleft()
        else:
            moves.append('R')
            a.pop()

    # Since we want the strictly increasing sequence length
    # We need to remove any duplicates and maintain order
    # This is a trick to find the longest increasing subsequence in `moves`
    longest_increasing_sequence_length = 0
    last_seen = {}
    current_length = 0

    for i, move in enumerate(moves):
        if move == 'L':
            num = a[i - current_length]
        else:
            num = a[n - (current_length + 1)]

        if num not in last_seen or last_seen[num] < longest_increasing_sequence_length:
            last_seen[num] = longest_increasing_sequence_length
            current_length += 1
            longest_increasing_sequence_length = max(longest_increasing_sequence_length, current_length)

    # Prepare the moves string for the longest sequence
    longest_moves = []
    last_num = 0
    for move in moves:
        if move == 'L':
            num = a.popleft()
        else:
            num = a.pop()

        if num > last_num:
            longest_moves.append(move)
            last_num = num

    return longest_increasing_sequence_length, ''.join(longest_moves)

